@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&family=Marcellus&display=swap');
:root{--ink:#e7dfc8;--muted:#948b76;--gold:#d9b66d;--red:#a6493c;--panel:rgba(20,19,17,.94);--line:rgba(223,196,135,.2)}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#10100f;color:var(--ink);font-family:'DM Sans',sans-serif}button{font:inherit;color:inherit}#game-shell{position:relative;width:100%;height:100%;min-height:480px;overflow:hidden;background:#171715}canvas{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at center,transparent 30%,rgba(0,0,0,.16) 72%,rgba(0,0,0,.58) 130%)}.topbar{position:absolute;z-index:2;top:0;left:0;right:0;height:77px;display:flex;align-items:center;padding:0 31px;background:linear-gradient(180deg,rgba(10,10,9,.88),rgba(10,10,9,.38));border-bottom:1px solid rgba(226,199,136,.13)}.brand{display:flex;align-items:center;gap:12px;width:33%}.brand-mark{font-size:23px;color:var(--gold);text-shadow:0 0 15px #e4b85c}.brand-name{font-family:Marcellus,serif;font-size:16px;letter-spacing:3.1px}.brand-sub,.stat-label,.eyebrow,.rail-title,.bottom-hint,.panel-foot,.start-foot{font:10px 'DM Mono',monospace;letter-spacing:1.55px;color:#8f8775}.brand-sub{font-size:8px;letter-spacing:2px;margin-top:3px}.run-stats{display:flex;gap:38px;justify-content:center;flex:1}.stat{display:grid;gap:4px;text-align:center}.stat-label{font-size:8px}.stat strong{font:16px 'DM Mono',monospace;color:#e5d7b4}.top-actions{width:33%;display:flex;justify-content:flex-end;gap:9px}.icon-btn{background:rgba(27,26,23,.7);border:1px solid var(--line);padding:9px 11px;color:#d9c99f;font-size:14px;cursor:pointer}.icon-btn span{font:9px 'DM Mono',monospace;letter-spacing:1px;padding:0 5px}.icon-btn kbd,.bag-button kbd{font:9px 'DM Mono',monospace;color:#857b65;border:1px solid #514937;padding:2px 4px}.hero-hud{position:absolute;z-index:2;top:94px;left:30px;width:255px;display:grid;gap:13px}.hero-name{display:flex;align-items:center;gap:10px}.class-icon{width:35px;height:35px;border:1px solid #8e7041;background:#27231a;color:#d8b15f;border-radius:50%;display:grid;place-items:center;font-size:20px}.hero-name b{font:12px 'DM Mono',monospace;letter-spacing:1.5px}.hero-name small{display:block;color:#9e9685;font-size:10px;margin-top:3px}.bars{display:grid;gap:8px}.bar{height:15px;position:relative;background:rgba(9,9,8,.78);border:1px solid rgba(198,180,141,.22);overflow:hidden}.bar span{height:100%;width:100%;display:block;transition:width .2s}.bar.hp span{background:linear-gradient(90deg,#752d29,#b54b3c)}.bar.xp span{background:linear-gradient(90deg,#96713c,#d8b45d)}.bar label{position:absolute;inset:1px 5px;display:flex;justify-content:space-between;font:8px 'DM Mono',monospace;letter-spacing:1px;color:#eee3c5}.bar label b{font-weight:400}.right-rail{position:absolute;z-index:2;right:22px;top:99px;width:174px}.rail-title{display:flex;justify-content:space-between;border-bottom:1px solid var(--line);padding:0 2px 8px;font-size:9px}.rail-title span{color:var(--gold)}.gear-slots{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin-top:10px}.gear-slot{aspect-ratio:1;border:1px solid rgba(196,178,132,.3);background:rgba(14,14,12,.76);display:grid;place-items:center;position:relative;font-size:19px;color:#726b5b}.gear-slot .slot-glyph{filter:drop-shadow(0 0 6px currentColor)}.gear-slot small{position:absolute;bottom:2px;left:0;right:0;text-align:center;font:6px 'DM Mono',monospace;color:#9a907a;letter-spacing:.5px}.bag-button{width:100%;margin-top:8px;padding:8px 7px;background:rgba(25,24,21,.78);border:1px solid var(--line);font:9px 'DM Mono',monospace;letter-spacing:1px;color:#d3c59f;cursor:pointer}.bag-button kbd{float:right}.relic-note{display:flex;gap:8px;margin:32px 4px;color:#837a68;font:italic 11px/1.5 Marcellus,serif}.relic-note i{font:30px Marcellus;color:#8a6935}.combat-feed{position:absolute;z-index:2;left:30px;bottom:58px;display:grid;gap:4px;pointer-events:none}.feed-line{font:10px 'DM Mono',monospace;color:#c5b88f;text-shadow:0 1px 3px #000;animation:fadefeed 4.5s forwards}.feed-line.loot{color:#e6c576}.feed-line.danger{color:#d67c69}@keyframes fadefeed{0%,75%{opacity:1}100%{opacity:0}}.pickup-prompt{position:absolute;z-index:2;left:50%;bottom:72px;transform:translateX(-50%);font:10px 'DM Mono',monospace;letter-spacing:1px;color:#f0d386;text-shadow:0 2px 8px #000;background:rgba(12,11,9,.8);border:1px solid #70582e;padding:9px 14px;display:none}.pickup-prompt kbd{border:1px solid #b09152;padding:2px 5px;margin-left:8px}.bottom-hint{position:absolute;z-index:2;bottom:18px;left:50%;transform:translateX(-50%);white-space:nowrap;font-size:8px;color:#a39a83}.bottom-hint i,.start-foot i,.panel-foot i{font-style:normal;color:#b29252;margin:0 6px}.keycap{border:1px solid rgba(210,192,146,.3);padding:3px 5px;color:#d3c69d;margin-right:3px}.modal-layer{position:absolute;inset:0;z-index:5;display:flex;align-items:center;justify-content:center;background:rgba(8,8,7,.28)}.modal-layer.off{display:none}.modal{position:relative;text-align:center;background:linear-gradient(145deg,rgba(30,28,23,.97),rgba(17,17,15,.98));border:1px solid rgba(205,174,107,.36);box-shadow:0 24px 100px #000;padding:35px 48px;min-width:400px}.modal:before,.modal:after{content:'';position:absolute;inset:6px;border:1px solid rgba(205,174,107,.1);pointer-events:none}.eyebrow{font-size:9px;color:#b69b63}.modal h1,.modal h2,.panel-head h2{font:32px Marcellus,serif;font-weight:400;letter-spacing:4px;margin:12px 0;color:#e9dfc8}.modal h1{font-size:40px;line-height:1.14;letter-spacing:5px}.modal h1 em{font-style:normal;color:#d7ad5c}.modal p{font-size:12px;line-height:1.7;color:#a59b85;margin:11px 0 21px}.start-modal{width:510px;padding-top:43px;padding-bottom:29px;overflow:hidden}.start-art{position:absolute;right:49px;top:113px;color:#9b7739;font-size:104px;opacity:.13;text-shadow:0 0 35px #dca642}.primary-btn{position:relative;z-index:1;background:linear-gradient(90deg,#96723c,#c5a45e);border:1px solid #dfbf78;padding:12px 22px;color:#17140e;font:11px 'DM Mono',monospace;letter-spacing:1.4px;cursor:pointer;min-width:220px;box-shadow:0 0 25px rgba(183,139,62,.13)}.primary-btn span{font-size:17px;margin-left:15px}.primary-btn:hover{filter:brightness(1.13)}.start-foot{font-size:8px;margin-top:25px;letter-spacing:1px}.hidden{display:none!important}.upgrade-options{display:flex;gap:10px;margin-top:20px}.upgrade-card{width:170px;min-height:150px;padding:14px 12px;text-align:left;background:#23211b;border:1px solid #6f5c35;cursor:pointer}.upgrade-card:hover{border-color:#e0bb68;background:#302a1f}.upgrade-card .upgrade-icon{font-size:24px;color:#d5ae60}.upgrade-card b{display:block;font:12px Marcellus,serif;color:#ead6a4;margin:8px 0}.upgrade-card small{font-size:10px;line-height:1.5;color:#a69b83}.inventory-panel{position:absolute;z-index:6;left:50%;top:50%;transform:translate(-50%,-50%);width:min(720px,94vw);max-height:88vh;overflow:auto;background:rgba(18,17,15,.97);border:1px solid rgba(212,177,103,.48);box-shadow:0 20px 100px #000;padding:24px 28px}.panel-head{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line);padding-bottom:13px}.panel-head h2{font-size:23px;letter-spacing:3px;margin:5px 0 0}.close-btn{border:1px solid var(--line);background:transparent;font-size:23px;width:32px;height:32px;cursor:pointer;color:#c5b68f}.inventory-columns{display:grid;grid-template-columns: .9fr 1.1fr;gap:25px;padding-top:15px}.inventory-columns h3{font:9px 'DM Mono',monospace;color:#b5a680;letter-spacing:1.4px;margin:4px 0 10px}.inventory-columns h3 span{float:right;color:#817863}.inventory-gear{display:grid;grid-template-columns:repeat(3,1fr);gap:6px}.inv-equip{min-height:75px;border:1px solid var(--line);background:#201f1a;padding:8px;font-size:20px}.inv-equip small{display:block;font:8px 'DM Mono',monospace;color:#968b73;margin-top:7px}.stat-sheet{display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-top:12px;font:9px 'DM Mono',monospace;color:#a89d83}.stat-sheet b{color:#dfc37c;font-weight:400;text-align:right}.inventory-list{display:grid;gap:6px;max-height:300px;overflow:auto}.loot-row{display:flex;align-items:center;gap:9px;border:1px solid #544733;background:#211f19;padding:8px;cursor:pointer;text-align:left}.loot-row:hover{background:#30291d;border-color:#c49b4d}.loot-row .loot-icon{font-size:21px;width:25px;text-align:center}.loot-row strong{display:block;font:11px Marcellus,serif}.loot-row small{display:block;font:8px 'DM Mono',monospace;color:#a1967c;margin-top:4px}.loot-row .equip-label{margin-left:auto;font:8px 'DM Mono',monospace;color:#d2ae61}.empty-bag{font:10px 'DM Mono',monospace;color:#807761;padding:20px 8px;text-align:center;border:1px dashed #504733}.panel-foot{border-top:1px solid var(--line);margin-top:16px;padding-top:11px;font-size:8px;text-align:center}.toast{position:absolute;z-index:8;top:88px;left:50%;transform:translate(-50%,-10px);opacity:0;transition:.3s;background:rgba(14,13,11,.94);border:1px solid #8f703b;padding:10px 18px;font:10px 'DM Mono',monospace;color:#e8ce8b;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.touch-controls{display:none}.modal-layer:not(.off)~.touch-controls{display:none}
@media(max-width:700px){.topbar{height:60px;padding:0 13px}.brand{width:auto;flex:1}.brand-name{font-size:12px;letter-spacing:2px}.brand-mark{font-size:19px}.run-stats{gap:12px;flex:1}.stat-label{font-size:6px}.stat strong{font-size:12px}.top-actions{width:auto}.icon-btn{padding:7px}.icon-btn span,.icon-btn kbd{display:none}.hero-hud{top:72px;left:13px;width:185px;gap:8px}.hero-name b{font-size:10px}.right-rail{top:73px;right:10px;width:112px}.gear-slots{gap:3px;margin-top:6px}.gear-slot{font-size:15px}.bag-button{font-size:7px;padding:7px 4px}.bag-button kbd{display:none}.relic-note{display:none}.bottom-hint{bottom:15px;font-size:6px;letter-spacing:.8px}.combat-feed{left:13px;bottom:75px}.modal{min-width:0;width:calc(100vw - 30px);padding:28px 20px}.start-modal{width:calc(100vw - 30px)}.modal h1{font-size:34px}.upgrade-options{flex-direction:column;max-height:55vh;overflow:auto}.upgrade-card{width:100%;min-height:85px}.inventory-panel{padding:17px 15px}.inventory-columns{gap:13px;grid-template-columns:.8fr 1.2fr}.inventory-columns h3{font-size:8px}.inventory-gear{grid-template-columns:repeat(2,1fr)}.inv-equip{min-height:58px;font-size:16px}.touch-controls{display:block;position:absolute;z-index:3;inset:auto 0 42px;pointer-events:none}.stick-zone{position:absolute;left:17px;bottom:0;width:112px;height:112px;border-radius:50%;border:1px solid rgba(210,192,146,.23);background:rgba(16,15,13,.35);pointer-events:auto;touch-action:none}.stick{position:absolute;left:32px;top:32px;width:46px;height:46px;border-radius:50%;background:rgba(205,173,104,.48);border:1px solid rgba(234,202,130,.65)}#dash-touch{position:absolute;right:18px;bottom:15px;border-radius:50%;width:62px;height:62px;background:rgba(110,52,40,.75);border:1px solid #b56851;font:9px 'DM Mono',monospace;pointer-events:auto;touch-action:none}.pickup-prompt{bottom:170px;white-space:nowrap}.start-foot{font-size:6px}.start-art{right:25px;top:115px}}

(()=>{
'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const $=s=>document.querySelector(s),rand=(a,b)=>a+Math.random()*(b-a),pick=a=>a[Math.floor(Math.random()*a.length)],clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const rarity={Common:{color:'#c7c0ae',weight:55},Magic:{color:'#73a7df',weight:28},Rare:{color:'#dfbd58',weight:13},Legendary:{color:'#df7850',weight:4}};
const types=['weapon','helm','armor','boots','ring','charm'],typeNames={weapon:'Weapon',helm:'Helm',armor:'Armor',boots:'Boots',ring:'Ring',charm:'Charm'},glyphs={weapon:'⚔',helm:'♙',armor:'⬟',boots:'◈',ring:'◎',charm:'✦'};
const prefixes=['Grim','Hollow','Cinder','Warden’s','Forsaken','Ashen','Mourning','Bloodied','Dusk','Pale'];
const bases={weapon:['Rustfang','Widowmaker','Bonecleaver','Nightbite','Oathkeeper'],helm:['Iron Visage','Crownsplitter','Dust Hood','Graveguard'],armor:['Pilgrim’s Mail','Blackened Hauberk','Ashweave','Last Stand'],boots:['Roadworn Treads','Fleetstep','Gravewalker','Mire Boots'],ring:['Ring of Embers','Widow’s Loop','Cold Promise','Ashen Band'],charm:['Saint’s Tooth','Hollow Locket','Black Sun','Griefstone']};
const affixes=['of the Fallen','of Embers','of Long Roads','of the Deep','of Ruin','of Stillness'];
let W=0,H=0,dpr=1,last=0,mode='menu',time=0,kills=0,wave=1,spawnTimer=0,shotTimer=0,enemyId=0,shake=0,toastTimer=0;
let player,enemies=[],shots=[],gems=[],drops=[],particles=[],decor=[],gear={},bag=[],upgrades=[],camera={x:0,y:0},keys={},touch={x:0,y:0},mouse={x:0,y:0};
const slotNames={weapon:'MAIN HAND',helm:'HEAD',armor:'BODY',boots:'FEET',ring:'RING',charm:'CHARM'};
const upgradePool=[['Quickened Hands','Your attacks strike faster.','☄',p=>p.fireRate*=1.22],['Long Reach','Projectiles fly farther and hit harder.','➶',p=>{p.damage*=1.22;p.range+=45}],['Vital Current','Increase maximum vitality and heal.','♥',p=>{p.maxHp+=25;p.hp=Math.min(p.maxHp,p.hp+35)}],['Fleetfoot','Move faster through the dead.','➤',p=>p.speed*=1.14],['Scavenger’s Eye','Find more experience in each slain foe.','✧',p=>p.xpBonus+=.22],['Second Wind','Recover a little vitality every few seconds.','✚',p=>p.regen+=.28],['Wider Arc','Your weapon catches more enemies.','✦',p=>p.pierce++],['Cinderheart','A chance to deal a brutal critical hit.','♦',p=>p.crit+=.08]];
function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
function newPlayer(){return{x:0,y:0,r:13,hp:100,maxHp:100,speed:175,damage:22,fireRate:.72,range:330,xp:0,nextXp:20,level:1,regen:0,xpBonus:0,pierce:0,crit:.05,dash:0,dashCd:0,invuln:0};}
function start(){player=newPlayer();enemies=[];shots=[];gems=[];drops=[];particles=[];bag=[];gear={};for(const t of types)gear[t]=null;time=0;kills=0;wave=1;spawnTimer=.5;shotTimer=.2;camera={x:0,y:0};mode='playing';$('#modal-layer').classList.add('off');$('#inventory-panel').classList.add('hidden');$('#feed').innerHTML='';refreshUI();addFeed('The Hollow March stirs…','');last=performance.now();}
function showToast(txt){let el=$('#toast');el.textContent=txt;el.classList.add('show');toastTimer=2.1}
function addFeed(text,kind=''){let el=document.createElement('div');el.className='feed-line '+kind;el.textContent=text;$('#feed').prepend(el);while($('#feed').children.length>4)$('#feed').lastChild.remove();setTimeout(()=>el.remove(),4700)}
function fmtTime(t){let m=Math.floor(t/60),s=Math.floor(t%60);return String(m).padStart(2,'0')+':'+String(s).padStart(2,'0')}
function refreshUI(){if(!player)return;$('#clock').textContent=fmtTime(time);$('#kills').textContent=kills;$('#wave').textContent=['I','II','III','IV','V','VI'][Math.min(5,Math.floor(time/90))];$('#level').textContent=player.level;$('#hp-fill').style.width=100*player.hp/player.maxHp+'%';$('#hp-text').textContent=Math.ceil(player.hp)+' / '+player.maxHp;$('#xp-fill').style.width=100*player.xp/player.nextXp+'%';$('#xp-text').textContent=player.xp+' / '+player.nextXp;drawGear();}
function rollRarity(){let n=Math.random()*100;return n<55?'Common':n<83?'Magic':n<96?'Rare':'Legendary'}
function createItem(){let type=pick(types),r=rollRarity(),mult={Common:1,Magic:1.55,Rare:2.25,Legendary:3.35}[r],stat=type==='weapon'?'damage':type==='boots'?'speed':type==='helm'||type==='armor'?'vitality':type==='ring'?'crit':'fireRate';let base=type==='weapon'?rand(3,8):type==='boots'?rand(8,18):type==='ring'?rand(1,3):type==='charm'?rand(.05,.12):rand(9,20);let value=Math.round(base*mult*10)/10;return{id:Math.random().toString(36).slice(2),type,rarity:r,name:pick(prefixes)+' '+pick(bases[type])+' '+pick(affixes),stat,value,icon:glyphs[type]}}
function statLabel(item){if(!item)return'';return item.stat==='damage'?'+'+item.value+' damage':item.stat==='speed'?'+'+item.value+'% speed':item.stat==='vitality'?'+'+item.value+' vitality':item.stat==='crit'?'+'+item.value+'% critical': '+'+item.value+'% attack speed'}
function applyItem(item,sign){let val=item.value*sign;if(item.stat==='damage')player.damage+=val;else if(item.stat==='speed')player.speed+=val;else if(item.stat==='vitality'){player.maxHp+=val;player.hp=clamp(player.hp+val,0,player.maxHp)}else if(item.stat==='crit')player.crit+=val/100;else player.fireRate*=1/(1+val/100)}
function equip(item){let old=gear[item.type];if(old)applyItem(old,-1);gear[item.type]=item;applyItem(item,1);bag=bag.filter(x=>x.id!==item.id);if(old&&bag.length<12)bag.push(old);showToast('EQUIPPED · '+item.name);addFeed('Equipped '+item.name,'loot');refreshUI();renderBag()}
function drawGear(){let box=$('#gear-slots');if(!box)return;box.innerHTML='';types.forEach(t=>{let it=gear[t],d=document.createElement('div');d.className='gear-slot';if(it)d.style.color=rarity[it.rarity].color;d.innerHTML=`<span class="slot-glyph">${it?it.icon:'·'}</span><small>${t.toUpperCase()}</small>`;d.title=it?it.name+' · '+statLabel(it):slotNames[t];box.appendChild(d)})}
function renderBag(){let list=$('#inventory-list');if(!list)return;$('#bag-count').textContent=bag.length+' / 12';list.innerHTML='';if(!bag.length)list.innerHTML='<div class="empty-bag">No relics yet.<br>Find glowing drops on the road.</div>';bag.forEach(it=>{let row=document.createElement('button');row.className='loot-row';row.style.borderLeft='2px solid '+rarity[it.rarity].color;row.innerHTML=`<span class="loot-icon" style="color:${rarity[it.rarity].color}">${it.icon}</span><span><strong>${it.name}</strong><small>${it.rarity.toUpperCase()} · ${statLabel(it)}</small></span><span class="equip-label">EQUIP ↗</span>`;row.onclick=()=>equip(it);list.appendChild(row)});let eq=$('#inventory-gear');eq.innerHTML='';types.forEach(t=>{let it=gear[t],d=document.createElement('div');d.className='inv-equip';d.style.borderColor=it?rarity[it.rarity].color:'#504a3b';d.innerHTML=`<span style="color:${it?rarity[it.rarity].color:'#726b5b'}">${it?it.icon:'·'}</span><small>${slotNames[t]}<br>${it?it.name:'Empty'}</small>`;eq.appendChild(d)});let totals=[['Damage',Math.round(player.damage)],['Attack rate',(1/player.fireRate).toFixed(1)+'/s'],['Move speed',Math.round(player.speed)],['Critical',Math.round(player.crit*100)+'%']];$('#stat-sheet').innerHTML=totals.map(x=>`<span>${x[0]}</span><b>${x[1]}</b>`).join('')}
function openBag(){if(mode!=='playing'&&mode!=='paused')return;renderBag();$('#inventory-panel').classList.remove('hidden');if(mode==='playing'){mode='paused';$('#modal-layer').classList.add('off')}}function closeBag(){ $('#inventory-panel').classList.add('hidden');if(mode==='paused')mode='playing'}
function levelUp(){mode='level';$('#modal-layer').classList.remove('off');$('.modal').classList.add('hidden');$('#level-modal').classList.remove('hidden');let choices=[...upgradePool].sort(()=>Math.random()-.5).slice(0,3);let cont=$('#upgrade-options');cont.innerHTML='';choices.forEach(u=>{let b=document.createElement('button');b.className='upgrade-card';b.innerHTML=`<span class="upgrade-icon">${u[2]}</span><b>${u[0]}</b><small>${u[1]}</small>`;b.onclick=()=>{u[3](player);player.level++;player.xp=0;player.nextXp=Math.floor(player.nextXp*1.35+6);mode='playing';$('#modal-layer').classList.add('off');addFeed('Level '+player.level+' · '+u[0],'loot');refreshUI();last=performance.now()};cont.appendChild(b)})}
function gainXp(v){player.xp+=Math.round(v*(1+player.xpBonus));if(player.xp>=player.nextXp){player.xp-=player.nextXp;player.level++;player.nextXp=Math.floor(player.nextXp*1.35+6);levelUp()}}
function spawnEnemy(){let angle=rand(0,Math.PI*2),dist=Math.max(W,H)*.62+rand(30,170),x=player.x+Math.cos(angle)*dist,y=player.y+Math.sin(angle)*dist;let elapsed=time,kind=Math.random()<Math.min(.38,.1+elapsed/450)?'brute':Math.random()<.28?'wisp':'ghoul';let base=kind==='brute'?{hp:90,speed:39,r:17,dmg:17,xp:7,color:'#8b5545'}:kind==='wisp'?{hp:23,speed:92,r:9,dmg:8,xp:3,color:'#8d7cab'}:{hp:38,speed:57,r:12,dmg:10,xp:4,color:'#a77950'};let scale=1+time/150;base.hp*=scale;base.dmg*=Math.sqrt(scale);enemies.push({id:++enemyId,x,y,...base,hp0:base.hp,flash:0,attack:0,kind})}
