function spawn(){let a=rand(0,6.28),d=Math.max(W,H)*.62+rand(40,160),kind=Math.random()<Math.min(.38,.1+time/450)?'brute':Math.random()<.28?'wisp':'ghoul',e=kind==='brute'?{hp:90,speed:39,r:17,dmg:17,xp:7,color:'#8b5545'}:kind==='wisp'?{hp:23,speed:92,r:9,dmg:8,xp:3,color:'#8d7cab'}:{hp:38,speed:57,r:12,dmg:10,xp:4,color:'#a77950'};e.hp*=1+time/150;e.hp0=e.hp;e.dmg*=Math.sqrt(1+time/150);Object.assign(e,{x:player.x+Math.cos(a)*d,y:player.y+Math.sin(a)*d,flash:0,attack:0,kind});enemies.push(e)}
