function collect(){let i=drops.findIndex(d=>Math.hypot(player.x-d.x,player.y-d.y)<78);if(i<0){if(drops.length)showToast('Move closer to a relic');return}let d=drops.splice(i,1)[0];if(bag.length>=12){drops.splice(i,0,d);showToast('Satchel full · open inventory');return}bag.push(d.item);feed('Found '+d.item.r+' '+d.item.type,'loot');showToast('FOUND · '+d.item.name);renderBag()}
function buildDecor(){decor=[];for(let i=0;i<230;i++)decor.push({x:rand(-2100,2100),y:rand(-2100,2100),r:rand(7,25),kind:Math.random()<.54?'stone':'bush',rot:rand(0,6.28),tone:rand(0,1)})}
function ground(){let sx=-((camera.x%96)+96)%96,sy=-((camera.y%96)+96)%96;ctx.fillStyle='#252522';ctx.fillRect(0,0,W,H);ctx.strokeStyle='rgba(179,166,135,.055)';for(let x=sx;x<W;x+=96){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let y=sy;y<H;y+=96){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}let ox=W/2-camera.x,oy=H/2-camera.y;decor.forEach(d=>{let x=ox+d.x,y=oy+d.y;if(x<-50||x>W+50||y<-50||y>H+50)return;ctx.save();ctx.translate(x,y);ctx.rotate(d.rot);if(d.kind==='stone'){ctx.fillStyle=d.tone>.5?'#34332e':'#2e2f2c';ctx.beginPath();ctx.ellipse(0,0,d.r,d.r*.63,0,0,6.28);ctx.fill();ctx.strokeStyle='rgba(125,118,99,.13)';ctx.stroke()}else{ctx.fillStyle='#242b24';ctx.beginPath();ctx.arc(0,0,d.r,0,6.28);ctx.fill()}ctx.restore()})}

